static int chanfind(struct luca_channel_registry*r,const char*n){for(unsigned i=0;i<r->count;i++)if(!luca_irc_casecmp(r->items[i].name,n))return (int)i;return-1;}
int luca_channel_registry_init(struct luca_channel_registry*r,const char*c){memset(r,0,sizeof *r);if(pthread_mutex_init(&r->mu,NULL))return-1;if(c&&*c){snprintf(r->items[0].name,sizeof r->items[0].name,"%s",c);r->items[0].wanted=1;r->count=1;}return 0;}
void luca_channel_registry_set(struct luca_channel_registry*r,const char*n,int w,int j,int p){if(!r||!n)return;pthread_mutex_lock(&r->mu);int i=chanfind(r,n);if(i<0&&r->count<LUCA_CHANNEL_CAP){i=(int)r->count++;snprintf(r->items[i].name,sizeof r->items[i].name,"%s",n);}if(i>=0){r->items[i].wanted=w;r->items[i].joined=j;r->items[i].parting=p;}pthread_mutex_unlock(&r->mu);}
void luca_channel_registry_observe(struct luca_channel_registry*r,const char*n,int j){if(!r||!n)return;pthread_mutex_lock(&r->mu);int i=chanfind(r,n);if(i<0&&r->count<LUCA_CHANNEL_CAP){i=(int)r->count++;snprintf(r->items[i].name,sizeof r->items[i].name,"%s",n);}if(i>=0){r->items[i].joined=j;r->items[i].parting=0;}pthread_mutex_unlock(&r->mu);}
static const char*ws(const char*p){while(*p==' '||*p=='\t'||*p=='\r'||*p=='\n')p++;return p;}
static int jstr(const char**pp,char*out,size_t n){const char*p=ws(*pp);size_t z=0;if(*p++!='"')return-1;while(*p&&*p!='"'){unsigned char c=(unsigned char)*p++;if(c=='\\'){c=(unsigned char)*p++;if(c=='"'||c=='\\'||c=='/'){}else if(c=='b')c='\b';else if(c=='f')c='\f';else if(c=='n')c='\n';else if(c=='r')c='\r';else if(c=='t')c='\t';else return-1;}if(c<0x20||z+1>=n)return-1;out[z++]=(char)c;}if(*p++!='"')return-1;out[z]=0;*pp=p;return 0;}
static int skipval(const char**pp){const char*p=ws(*pp);if(*p=='"'){p++;while(*p){if(*p++=='"')break;if(p[-1]=='\\'&&*p)p++;}if(p[-1]!='"')return-1;*pp=p;return 0;}if(*p=='{'||*p=='['){char open=*p++,close=open=='{'?'}':']';int d=1,in=0,esc=0;while(*p&&d){char c=*p++;if(in){if(esc)esc=0;else if(c=='\\')esc=1;else if(c=='"')in=0;}else if(c=='"')in=1;else if(c==open)d++;else if(c==close)d--;}if(d)return-1;*pp=p;return 0;}while(*p&&*p!=','&&*p!='}')p++;*pp=p;return 0;}
static int objfield(const char*s,const char*k,char*out,size_t n){const char*p=ws(s);char key[80];int found=0;if(*p++!='{')return-1;for(;;){p=ws(p);if(*p=='}')return found?0:-1;if(jstr(&p,key,sizeof key))return-1;p=ws(p);if(*p++!=':')return-1;p=ws(p);if(!strcmp(key,k)){if(found||jstr(&p,out,n))return-1;found=1;}else if(skipval(&p))return-1;p=ws(p);if(*p==','){p++;continue;}if(*p=='}'){p++;return found?0:-1;}return-1;}}
static int paramsfield(const char*s,const char*k,char*out,size_t n){const char*p=ws(s),key[80];if(*p++!='{')return-1;for(;;){p=ws(p);if(*p=='}')return-1;if(jstr(&p,key,sizeof key))return-1;p=ws(p);if(*p++!=':')return-1;p=ws(p);if(!strcmp(key,"params")){if(*p!='{')return-1;return objfield(p,k,out,n);}if(skipval(&p))return-1;p=ws(p);if(*p==','){p++;continue;}return-1;}}
